    [0, 0, 0, 0, 0, 0, 0]
]

hole = (1, 3)

directions_4 = [(-1,0), (1,0), (0,-1), (0,1)]

# For each cell, find all cells reachable using ONLY steps toward or away from the hole
def directional_reach(grid, start, target, directions):
    rows, cols = len(grid), len(grid[0])

    # Only allow moves that go directly toward or away from target
    dr_to_target = target[0] - start[0]
    dc_to_target = target[1] - start[1]

    # Directions must be aligned with direction to/from target
    allowed = []
    if dr_to_target >= 0:
        allowed.append((1, 0))  # South
    if dr_to_target <= 0:
        allowed.append((-1, 0))  # North
    if dc_to_target >= 0:
        allowed.append((0, 1))  # East  
    if dc_to_target <= 0:
        allowed.append((0, -1))  # West

    visited = {start}
    queue = deque([start])

    while queue:
        cr, cc = queue.popleft()

        for dr, dc in allowed:
            nr, nc = cr+dr, cc+dc
            if 0<=nr<rows and 0<=nc<cols:
                if grid[nr][nc] == 8 and (nr,nc) not in visited:
                    visited.add((nr,nc))
                    queue.append((nr,nc))

    return visited

